
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_dldf_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_dldf", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.867037885198511e-02, -7.887970950265374e-02, -7.919484286187663e-02, -7.967595478607126e-02, -8.042078682182088e-02, -8.158154176784543e-02, -8.334896776521163e-02, -8.569709197739793e-02, -8.694955600630169e-02, -7.955907730946717e-02, -5.911298251785438e-02, -5.976678547718841e-02, -4.253477457151429e-02, -4.103071192255220e-02, -3.518080984403308e-02, -2.762463378535427e-03, 1.815815647130156e-02, 6.517841057670737e-03, 6.344178519117630e-04, 1.460105111954135e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


